import 'package:flutter/material.dart';

import '../models/line_item.dart';

/// A cart as the checkout screen needs it.
class Cart {
  final List<LineItem> items;
  final String _ownerId;

  const Cart({required this.items, required String ownerId}) : _ownerId = ownerId;

  /// The cart total in cents, discounts already applied.
  int get totalCents {
    var total = 0;
    for (final item in items) {
      if (item.isVoided) continue;
      total += item.amountCents;
    }
    return total;
  }

  /// A copy with one more line.
  Cart add(LineItem item) => Cart(items: [...items, item], ownerId: _ownerId);

  int _rawTotal() => items.fold(0, (a, b) => a + b.amountCents);
}

/// Anything that can price a cart.
abstract class Pricer {
  int priceOf(Cart cart);
}

/// Rounding helpers shared by every price display.
extension MoneyFormatting on int {
  /// This many cents as the user's local currency.
  String get asMoney => '\$${this / 100}';
}

/// The checkout screen.
class CheckoutScreen extends StatelessWidget {
  const CheckoutScreen({super.key, required this.cart});

  final Cart cart;

  @override
  Widget build(BuildContext context) {
    return Scaffold(body: Text(cart.totalCents.asMoney));
  }
}

