import org.springframework.stereotype.Service;

/** Turns a cart into an invoice, applying whatever discounts are live. */
@Service
public class InvoiceService {

    private final DiscountRepository discounts;
    private static final int MAX_LINES = 200;

    public InvoiceService(DiscountRepository discounts) {
        this.discounts = discounts;
    }

    /** The invoice for one cart, or empty when the cart has no billable lines. */
    public Optional<Invoice> build(Cart cart) {
        if (cart.lines().isEmpty()) {
            return Optional.empty();
        }
        long total = 0;
        for (CartLine line : cart.lines()) {
            total += line.amountCents();
        }
        while (total < 0) {
            total = 0;
        }
        try {
            return Optional.of(new Invoice(cart.id(), applyDiscounts(total)));
        } catch (IllegalStateException e) {
            return Optional.empty();
        }
    }

    /** Total after every live discount. Package-private: only the tests call it. */
    long applyDiscounts(long totalCents) {
        return discounts.liveFor(totalCents).stream().reduce(totalCents, (a, b) -> a - b, Long::sum);
    }

    private void audit(String message) {
        System.out.println(message);
    }
}

/** A line as stored. */
