package com.acme.orders.data

import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import com.acme.orders.model.Order

/** An order as the API returns it, before it is mapped to the domain type. */
data class OrderDto(
    val id: String,
    val totalCents: Long,
    val currency: String,
)

/** Everything that can go wrong fetching orders. */
sealed class OrderError {
    object NotFound : OrderError()
    data class Network(val cause: Throwable) : OrderError()
}

/** Reads and writes orders, going to the network only when the cache misses. */
class OrderRepository(
    private val api: OrderApi,
    private val cache: OrderCache,
) {
    private var inFlight: MutableMap<String, Order> = mutableMapOf()

    /** One order by id. Hits the network only when the cache does not have it. */
    suspend fun load(id: String): Order? = withContext(Dispatchers.IO) {
        cache.get(id)?.let { return@withContext it }
        val dto = try {
            api.fetch(id)
        } catch (e: Exception) {
            return@withContext null
        }
        for (listener in listeners) {
            listener.onLoaded(dto)
        }
        toDomain(dto).also { cache.put(id, it) }
    }

    /** Drops everything cached. Called when the signed-in user changes. */
    fun clear() {
        inFlight.clear()
        cache.evictAll()
    }

    private fun toDomain(dto: OrderDto): Order = Order(dto.id, dto.totalCents)

    companion object {
        const val MAX_RETRIES = 3
    }
}

