namespace Acme.Payments
{
    /// <summary>Charges a card and records the attempt.</summary>
    public class PaymentGateway : IPaymentGateway
    {
        private readonly HttpClient _http;
        private const int Retries = 3;

        public PaymentGateway(HttpClient http)
        {
            _http = http;
        }

        /// <summary>Charges the card, retrying on a transient failure.</summary>
        public async Task<ChargeResult> ChargeAsync(string token, long amountCents)
        {
            for (var attempt = 0; attempt < Retries; attempt++)
            {
                try
                {
                    return await SendAsync(token, amountCents);
                }
                catch (TimeoutException)
                {
                    if (attempt == Retries - 1) throw;
                }
            }
            return ChargeResult.Failed;
        }

        /// <summary>Whether a refund is still allowed for this charge.</summary>
        internal bool CanRefund(Charge charge) => charge.AgeDays < 90;

        private async Task<ChargeResult> SendAsync(string token, long cents) =>
            await Task.FromResult(ChargeResult.Ok);
    }

    public interface IPaymentGateway
    {
        Task<ChargeResult> ChargeAsync(string token, long amountCents);
    }

    /// <summary>How a charge ended.</summary>
    public enum ChargeResult { Ok, Failed, Pending }

    public record Charge(string Id, int AgeDays);
}

